<?php
namespace Tests\Feature;use App\Models\{FeedbackResponse,Institution,Survey,User};use Database\Seeders\RolesAndPermissionsSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class FeedbackCorrelationTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(RolesAndPermissionsSeeder::class);}private function context():array{$u=User::factory()->create();$u->assignRole('Network Admin');$i=Institution::create(['name'=>'T','slug'=>'t']);$c=$i->campuses()->create(['name'=>'M','code'=>'M']);$b=$c->buildings()->create(['name'=>'B','code'=>'B']);$f=$b->floors()->create(['name'=>'G','code'=>'G','level_number'=>0]);$a=$f->surveyAreas()->create(['name'=>'East','code'=>'E']);$fp=$f->floorPlans()->create(['uploaded_by'=>$u->id,'original_name'=>'p','file_path'=>'p','mime_type'=>'image/png','file_size'=>1,'version'=>1]);$s=Survey::create(['floor_id'=>$f->id,'floor_plan_id'=>$fp->id,'survey_area_id'=>$a->id,'created_by'=>$u->id,'name'=>'S']);$p=$s->points()->create(['floor_plan_id'=>$fp->id,'survey_area_id'=>$a->id,'captured_by'=>$u->id,'x_normalized'=>.2,'y_normalized'=>.3,'source_type'=>'measured','collection_method'=>'manual','validation_status'=>'valid','captured_at'=>now()]);$p->measurements()->create(['rssi_dbm'=>-80,'latency_ms'=>120,'source_type'=>'measured','collection_method'=>'manual','captured_at'=>now()]);return[$u,$c,$b,$f,$a];}public function test_public_feedback_is_stored_and_correlated():void{[$u,$c,$b,$f,$a]=$this->context();$this->post('/feedback',['campus_id'=>$c->id,'building_id'=>$b->id,'floor_id'=>$f->id,'survey_area_id'=>$a->id,'problem_type'=>'weak_signal','connection_stability'=>'frequently_unstable','speed_satisfaction'=>2,'overall_satisfaction'=>2,'activity_type'=>'video_call','experienced_at'=>now()->format('Y-m-d H:i:s'),'consent'=>1])->assertRedirect();$this->assertDatabaseCount('feedback_responses',1);$this->assertDatabaseCount('feedback_correlations',1);}public function test_feedback_without_measurements_remains_insufficient():void{[$u,$c,$b,$f,$a]=$this->context();\App\Models\Measurement::query()->delete();$this->post('/feedback',['campus_id'=>$c->id,'building_id'=>$b->id,'floor_id'=>$f->id,'problem_type'=>'slow_connection','connection_stability'=>'occasionally_unstable','speed_satisfaction'=>2,'overall_satisfaction'=>3,'activity_type'=>'web_browsing','experienced_at'=>now()->format('Y-m-d H:i:s'),'consent'=>1])->assertRedirect();$this->assertDatabaseCount('feedback_correlations',0);}}
